(function(){
var img=document.querySelector('.hero img');
if(!img)return;
var v=document.createElement('video');
v.className='intro';
v.muted=true;v.defaultMuted=true;v.setAttribute('muted','');v.playsInline=true;v.setAttribute('playsinline','');
v.preload='auto';v.autoplay=true;v.loop=false;
v.poster='data:image/jpeg;base64,';
v.setAttribute('aria-label',img.getAttribute('alt')||'Kemix');
v.src='data:video/mp4;base64,';
img.parentNode.replaceChild(v,img);
var pr=v.play();if(pr&&pr.catch)pr.catch(function(){});
})();
